import { type DeviceState, defineDevice } from "@audio-ui/core/device";
import { TRANSIENT_KERNELS } from "@/components/audio-ui/devices/transient/kernels";
import { manifestWorklet } from "@/lib/manifest-worklet";

/** How far ahead of the signal the detector reads, in seconds: the audio waits this long so the gain is already up when a hit arrives. It is the latency of the device. */
export const LOOKAHEAD_SECONDS = 0.001;

/**
 * A transient shaper as a device: it turns the attack of a sound up or down
 * and the sustain after it up or down, whatever the level of the sound, with
 * no panel and no audio in it. A drum loses its click or gains it, a pluck
 * rings longer or shorter, and none of it needs a threshold. Its clean model
 * reads the attack ahead of the sound; its follower model is the transient
 * shaper of `@audio/dynamics-transient-shaper`.
 */
export const transientDevice = defineDevice({
  description:
    "Shapes the attack and the sustain of a sound: the attack is the moment a hit starts, the sustain is what rings after it, and each is turned up or down by up to 12 dB, at any level of the signal, with an output gain. Its model is clean, which tells the attack by how far the peak rises over itself smoothed over 25 ms and moves the gain in decibels, or follower, which tells it by how far the level rises over a copy of it 50 times slower and moves the gain in a line between the attack's and the sustain's.",
  id: "audioui.transient",
  // The audio waits for the detector, on or off, so the delay is the same either way.
  latency: () => LOOKAHEAD_SECONDS,
  name: "Transient shaper",
  parameters: [
    { default: true, id: "enabled", kind: "toggle", label: "On" },
    {
      default: "clean",
      id: "model",
      kind: "choice",
      label: "Model",
      options: [
        { label: "Clean", value: "clean" },
        { label: "Follower", value: "follower" },
      ],
    },
    {
      default: 6,
      id: "attackDb",
      label: "Attack",
      max: 12,
      min: -12,
      step: 0.5,
      unit: "dB",
    },
    {
      default: 0,
      id: "sustainDb",
      label: "Sustain",
      max: 12,
      min: -12,
      step: 0.5,
      unit: "dB",
    },
    {
      default: 0,
      id: "outputDb",
      label: "Output",
      max: 12,
      min: -12,
      step: 0.5,
      unit: "dB",
    },
  ],
});

export type TransientState = DeviceState<typeof transientDevice.parameters>;

/** The numbers that go on the nodes for a state. Off, the shaping is nothing and the output is unity. */
export function transientSettings(state: TransientState) {
  const on = state.enabled;
  return {
    attack: on ? state.attackDb : 0,
    model: state.model,
    /** What the follower model plays, in its manifest's units: the gain added on an attack and on the sustain, as a share, so an attack all attack gets the decibels asked. */
    modelParams: {
      attackGain: 10 ** (state.attackDb / 20) - 1,
      sustainGain: 10 ** (state.sustainDb / 20) - 1,
    },
    modelWet: on && state.model !== "clean" ? 1 : 0,
    output: on ? 10 ** (state.outputDb / 20) : 1,
    sustain: on ? state.sustainDb : 0,
  };
}

/**
 * The processor of the shaper, as the source of an `AudioWorklet`. It reads
 * the signal and writes the gain to apply, one value per sample. Two views
 * of the signal's peak, which jumps up and falls over 15 ms so a low note does
 * not ripple it, the peak itself and the same peak smoothed over 25 ms, meet
 * when a sound holds and part when a hit starts: how far the peak is over the
 * smoothed one, in dB, says how much of the moment is attack (6 dB or more is
 * all of it), and the rest is sustain. The gain in dB is the attack
 * amount times the attack share plus the sustain amount times the sustain
 * share, smoothed over a millisecond. It does not depend on the level of the
 * signal, only on the shape of its envelope. The engine loads it from a blob,
 * so there is no file to serve.
 */
export const TRANSIENT_WORKLET = `
class AudioUiTransient extends AudioWorkletProcessor {
  static get parameterDescriptors() {
    return [
      { name: "attack", defaultValue: 0, minValue: -24, maxValue: 24, automationRate: "k-rate" },
      { name: "sustain", defaultValue: 0, minValue: -24, maxValue: 24, automationRate: "k-rate" }
    ];
  }
  constructor() {
    super();
    this.peak = 0;
    this.slow = 0;
    this.gainDb = 0;
  }
  process(inputs, outputs, parameters) {
    const input = inputs[0];
    const out = outputs[0][0];
    if (!out) return true;
    const attackDb = parameters.attack[0];
    const sustainDb = parameters.sustain[0];
    const fall = Math.exp(-1 / (0.015 * sampleRate));
    const slowStep = 1 - Math.exp(-1 / (0.025 * sampleRate));
    const smooth = 1 - Math.exp(-1 / (0.001 * sampleRate));
    for (let n = 0; n < out.length; n += 1) {
      let peak = 0;
      for (let c = 0; c < input.length; c += 1) {
        const v = Math.abs(input[c][n]);
        if (v > peak) peak = v;
      }
      this.peak = peak > this.peak ? peak : this.peak * fall;
      this.slow += (this.peak - this.slow) * slowStep;
      let target = 0;
      if (this.slow > 0.0001) {
        const difference = 20 * Math.log10((this.peak + 1e-6) / (this.slow + 1e-6));
        const share = Math.min(1, Math.max(0, difference / 6));
        target = attackDb * share + sustainDb * (1 - share);
      }
      this.gainDb += (target - this.gainDb) * smooth;
      out[n] = Math.pow(10, this.gainDb / 20);
    }
    return true;
  }
}
registerProcessor("audioui-transient", AudioUiTransient);
`;

/**
 * The source of the follower model's `AudioWorklet`, processor
 * `audioui-transient-follower`: the manifest of
 * `@audio/dynamics-transient-shaper`, played by `manifestWorklet`. Its
 * attack and sustain change as it plays.
 */
export const TRANSIENT_FOLLOWER_WORKLET = manifestWorklet({
  kernels: TRANSIENT_KERNELS,
  models: { follower: "transientShaper" },
  processor: "audioui-transient-follower",
});

/**
 * audio.js kernels, each module as published, in its own scope, for an
 * `AudioWorklet`, which cannot import them:
 * - `@audio/dynamics-transient-shaper` 0.1.6 (MIT, Dmitry Iv.): `transientShaper`, as `module0`
 * - `@audio/dynamics-transient-shaper` 0.1.6 (MIT, Dmitry Iv.): `transientShaper`
 */
export const TRANSIENT_KERNELS = `const module0 = (() => {
/**
 * Transient shaper — independently boosts/cuts attack and sustain portions.
 * A level follower (1 ms attack, 100 ms release) and a slow follower of that level
 * (50 ms attack, instant release) separate transient from sustain.
 */

let {abs, exp} = Math

function transientShaper (data, params) {
	let attackGain = params.attackGain ?? 0     // linear gain delta: >0 emphasize, <0 suppress
	let sustainGain = params.sustainGain ?? 0
	let fs = params.fs || 44100

	let aFast = exp(-1 / (0.001 * fs))
	let aSlow = exp(-1 / (0.05 * fs))
	let aRel = exp(-1 / (0.1 * fs))

	let envFast = params._envFast ?? 0
	let envSlow = params._envSlow ?? 0

	for (let i = 0, l = data.length; i < l; i++) {
		let x = data[i]
		let xAbs = abs(x)

		// Level: fast attack, slow release
		envFast = xAbs > envFast ? aFast * envFast + (1 - aFast) * xAbs : aRel * envFast
		// Slow copy of the level: rises 50× slower, falls with it, so it never exceeds it
		envSlow = envFast > envSlow ? aSlow * envSlow + (1 - aSlow) * envFast : envFast

		// Transient share of the level, 0..1: near 1 on attacks, near 0 on held material
		let transient = envFast > 1e-10 ? (envFast - envSlow) / envFast : 0

		// Gain stays within 1 + [min, max] of the two gains
		let gain = 1 + attackGain * transient + sustainGain * (1 - transient)
		data[i] = x * gain
	}

	params._envFast = envFast
	params._envSlow = envSlow

	return data
}

return { transientShaper, default: transientShaper };
})();

const transientShaper = (() => {
const { default: transientShaperCurve } = module0;
// atom manifest — wraps the transient shaper kernel per @audio/compile CONTRACT.
// The kernel is causal (fast/slow envelope, no lookahead) and carries its continuation
// state (_envFast/_envSlow) on the options object passed in, mutating it in place. We
// own one such state object per channel in closure (fs fixed at construction; the
// kernel's own fixed 1ms/50ms envelope time constants aren't parameterized, so nothing
// needs \`restart\`) and refresh attackGain/sustainGain from the live params every block
// before calling the kernel directly on the (copied) output buffer.
//
// KNOWN KERNEL DEFECT (not fixed here — out of scope for a manifest wrapper): the
// kernel's \`transient = diff/envSlow\` ratio (transient-shaper.js) is unbounded. Right
// after a cold start or a near-silent passage, envSlow sits near zero while envFast
// rises fast, so the ratio — and thus the output gain — can spike to 30-40x for a few
// milliseconds. \`attackGain\`/\`sustainGain\` are range-limited to [-1, 2] here to keep
// that spike survivable, but the instability is in the kernel's math, not the range.

const transientShaper = (ctx) => {
	const states = []
	for (let c = 0, N = ctx.maxChannels ?? 8; c < N; c++) states.push({
		fs: ctx.sampleRate,
		attackGain: ctx.params.attackGain[0],
		sustainGain: ctx.params.sustainGain[0],
		_envFast: 0,
		_envSlow: 0,
	})
	return (inputs, outputs, params) => {
		const inp = inputs[0], out = outputs[0]
		if (!inp || !inp.length) return
		const attackGain = params.attackGain[0], sustainGain = params.sustainGain[0]
		for (let c = 0; c < inp.length; c++) {
			const st = states[c]
			st.attackGain = attackGain
			st.sustainGain = sustainGain
			out[c].set(inp[c])
			transientShaperCurve(out[c], st)
		}
	}
}
transientShaper.channels = 'any'
transientShaper.tail = 0
transientShaper.params = {
	attackGain:  { type: 'number', min: -1, max: 2, default: 0 },
	sustainGain: { type: 'number', min: -1, max: 2, default: 0 },
}

return transientShaper;
})();
`;
